What is printed by this string reversal program?

```c
#include <stdio.h>
#include <string.h>

void strReverse(char *s) {
    int i = 0, j = strlen(s) - 1;
    while (i < j) {
        char temp = s[i];
        s[i] = s[j];
        s[j] = temp;
        i++;
        j--;
    }
}

int main(void) {
    char word[] = "radar";
    strReverse(word);
    printf("%s", word);
    return 0;
}
```

