What is the output of this program when copying `"ComputerScience"` into a buffer of size 6?

```c
#include <stdio.h>
#include <string.h>

void safeCopy(char *dest, const char *src, size_t destSize) {
    if (destSize == 0) return;
    size_t i;
    for (i = 0; i < destSize - 1 && src[i] != '\0'; i++) {
        dest[i] = src[i];
    }
    dest[i] = '\0';
}

int main(void) {
    char buffer[6];
    safeCopy(buffer, "ComputerScience", sizeof(buffer));
    printf("%s", buffer);
    return 0;
}
```

What is printed by this palindrome checking program?

```c
#include <stdio.h>
#include <string.h>
#include <stdbool.h>

bool isPalindrome(const char *s) {
    int left = 0, right = strlen(s) - 1;
    while (left < right) {
        if (s[left] != s[right]) return false;
        left++;
        right--;
    }
    return true;
}

int main(void) {
    printf("%d %d", isPalindrome("madam"), isPalindrome("nile"));
    return 0;
}
```
